/*
 * A132431  For n>0, let B_n be the subsemigroup of the full transformation
 *          monoid on the n-set [n] generated by the following functions: Let
 *          x be a certain element in [n]. Now the generators of B are those
 *          functions which map either x to any distinct element y in [n]
 *          leaving all the other elements fixed, or...
 * https://oeis.org/A132431
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nice, nonn
 * Formula:   a(n) = n^n - n*(n-1)^(n-1) - (n-1)*n! + n*(n-1)
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 9, u64 n <= 16, u128 n <= 27,
 *            big any n
 * Helpers:   big_pow, factorial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/big_pow.h"
#include "../utils/factorial.h"

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* not used, but safety */

    /* n^n */
    seq_t term1 = big_pow((seq_t)n, (seq_t)n);

    /* n*(n-1)^(n-1) */
    seq_t term2 = big_pow((seq_t)(n - 1), (seq_t)(n - 1));
    term2 = term2 * (seq_t)n;

    /* (n-1)*n! */
    seq_t term3 = factorial(n);
    term3 = term3 * (seq_t)(n - 1);

    /* n*(n-1) */
    seq_t term4 = (seq_t)n * (seq_t)(n - 1);

    /* a(n) = term1 - term2 - term3 + term4 */
    seq_t result = term1;
    result = result - term2;
    result = result - term3;
    result = result + term4;

    return result;
}
